// Page-level SEO metadata. Every page should build its `metadata` with
// pageMetadata() so it gets a canonical URL and matching Open Graph / Twitter
// tags — Next.js replaces (rather than merges) the layout's openGraph object,
// so a page that sets only title/description would share the site's preview.
//
// The share image is generated by app/opengraph-image.tsx and twitter-image.tsx.
// Next.js only attaches those automatically to pages that don't set their own
// openGraph, so pageMetadata() references them explicitly.

import type { Metadata } from "next";
import { publicPages } from "@/config/navigation";
import { siteConfig } from "@/config/site";

type PageSeo = {
  title: string;
  description: string;
  /** Path of the page, e.g. "/loan-eligibility". Used for the canonical URL. */
  path: string;
  /** Use the title as-is instead of applying the "%s | TeboTec" template. */
  absoluteTitle?: boolean;
  /** Keep the page out of search results (e.g. pages with personal data). */
  noindex?: boolean;
};

/** Matches the exports in app/opengraph-image.tsx and app/twitter-image.tsx. */
const shareImage = {
  width: 1200,
  height: 630,
  alt: `${siteConfig.name}: ${siteConfig.tagline}`,
  type: "image/png",
};

/** Open Graph fields shared by every page. */
export const baseOpenGraph = {
  type: "website" as const,
  siteName: siteConfig.name,
  locale: siteConfig.locale.replace("-", "_"),
  images: [{ url: "/opengraph-image", ...shareImage }],
};

/** Twitter/X card fields shared by every page. */
export const baseTwitter = {
  card: "summary_large_image" as const,
  images: [{ url: "/twitter-image", ...shareImage }],
};

export function pageMetadata({ title, description, path, absoluteTitle, noindex }: PageSeo): Metadata {
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    // Relative to metadataBase; strips query strings such as ?period=7d so
    // filtered views aren't treated as separate pages.
    alternates: { canonical: path },
    openGraph: { ...baseOpenGraph, title, description, url: path },
    twitter: { ...baseTwitter, title, description },
    ...(noindex && { robots: { index: false, follow: false } }),
  };
}

/** Metadata for a page listed in `publicPages`, so it matches the sitemap and llms.txt. */
export function publicPageMetadata(
  path: string,
  options: Partial<Pick<PageSeo, "title" | "description" | "absoluteTitle">> = {},
) {
  const page = publicPages.find((candidate) => candidate.href === path);
  if (!page) throw new Error(`No public page registered for ${path}`);
  return pageMetadata({
    title: options.title ?? page.title,
    description: options.description ?? page.description,
    path: page.href,
    absoluteTitle: options.absoluteTitle,
  });
}
